## 5. 캐시 친화적 알고리즘

### 예 1: 행렬 곱셈

```c
// ❌ 캐시 비친화적 (열 우선 접근)
void matmul_bad(float A[N][N], float B[N][N], float C[N][N]) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            float sum = 0;
            for (int k = 0; k < N; k++) {
                sum += A[i][k] * B[k][j];  // B[k][j] = 불규칙 접근
            }
            C[i][j] = sum;
        }
    }
}
// 캐시 미스: 높음 (열 접근)

// ✅ 캐시 친화적 (행 우선 + 블로킹)
#define BLOCK_SIZE 64

void matmul_good(float A[N][N], float B[N][N], float C[N][N]) {
    // B 전치 (행 우선 접근)
    float B_T[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            B_T[i][j] = B[j][i];
        }
    }

    // 블록 단위 곱셈 (L3 캐시에 맞음)
    for (int bi = 0; bi < N; bi += BLOCK_SIZE) {
        for (int bj = 0; bj < N; bj += BLOCK_SIZE) {
            for (int bk = 0; bk < N; bk += BLOCK_SIZE) {
                for (int i = bi; i < bi + BLOCK_SIZE; i++) {
                    for (int j = bj; j < bj + BLOCK_SIZE; j++) {
                        float sum = C[i][j];
                        for (int k = bk; k < bk + BLOCK_SIZE; k++) {
                            sum += A[i][k] * B_T[j][k];
                        }
                        C[i][j] = sum;
                    }
                }
            }
        }
    }
}

성능:
일반: 1ms (200x200 행렬)
최적화: 0.1ms (10배 향상)
```

### 예 2: 링크드 리스트 vs 배열

```go
// ❌ 캐시 비친화적 (링크드 리스트)
type Node struct {
    Value int
    Next  *Node
}

list := &Node{1, &Node{2, &Node{3, ...}}}

for n := list; n != nil; n = n.Next {
    sum += n.Value  // 포인터 추종 = 캐시 미스
}
// 캐시 미스: 매우 높음 (매 노드마다)

// ✅ 캐시 친화적 (배열)
arr := []int{1, 2, 3, ...}

for i := 0; i < len(arr); i++ {
    sum += arr[i]  // 순차 접근 = 캐시 히트
}
// 캐시 미스: 거의 없음 (prefetch)

성능 (100만 요소):
링크드 리스트: 500ms
배열: 5ms (100배!)
```

