# L3 캐시 미스 자세히
perf stat -e LLC-loads,LLC-load-misses ./program
```

### Go 벤치마크로 확인

```go
func BenchmarkSoA(b *testing.B) {
    points := Points{
        X: make([]float32, 1000000),
        Y: make([]float32, 1000000),
        Z: make([]float32, 1000000),
    }

    b.ResetTimer()
    for i := 0; i < b.N; i++ {
        for j := range points.X {
            points.X[j] *= 2
        }
    }
}

// 결과
// BenchmarkSoA-8   1000    1005493 ns/op  (~1ms)
```

